package net.neoforged.neoforge.client.event;public class InputEvent{public static class InteractionKeyMappingTriggered{public final boolean use;public boolean canceled,swing=true;public InteractionKeyMappingTriggered(boolean use){this.use=use;}public boolean isCanceled(){return canceled;}public boolean isUseItem(){return use;}public boolean isAttack(){return !use;}public boolean isPickBlock(){return false;}public void setCanceled(boolean b){canceled=b;}public void setSwingHand(boolean b){swing=b;}}public static class MouseButton{public static class Post{public final int button,action;public Post(int b,int a){button=b;action=a;}public int getButton(){return button;}public int getAction(){return action;}}}}
